// Vulnerable: Using java.net.URL without proper validation can lead to SSRF attacks
public class BadExample {
    public static void main(String[] args) {
        try {
            // Vulnerable: Directly using user input in URL without validation
            String userInput = "http://internal-api:8080/secret";
            java.net.URL url = new java.net.URL(userInput);
