}
***
// Good: Proper validation and use of URL with checks for internal hosts
public class GoodExample {
    public static void main(String[] args) {
        try {
            // Validating the URL to prevent SSRF attacks
            String userInput = "http://internal-api:8080/secret";
            java.net.URL url = new java.net.URL(userInput);
            java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();

            // Check if the URL is pointing to an internal host
            if (isInternalHost(url.getHost())) {
                System.out.println("Access to internal host is not allowed.");
                return;
            }

            connection.setRequestMethod("GET");
            int responseCode = connection.getResponseCode();
            System.out.println("Response Code: " + responseCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Helper method to check if the host is internal
    private static boolean isInternalHost(String host) {
        // Example: Check if the host is in a known internal network range
        return host.contains("internal-api") || host.contains("localhost") || host.contains("127.0.0.1");
    }
}
