***
[extrait de code 2]  
```java
// Correct : Utilisation sécurisée de la classe java.lang.ClassLoader avec validation des entrées utilisateur
String className = request.getParameter("className"); // Entrée utilisateur non filtrée
// Vérification de la validité du nom de classe
if (className != null && className.matches("^\\w+$")) {
    try {
        Class<?> clazz = Class.forName(className);
        Object instance = clazz.getDeclaredConstructor().newInstance();
        // Utilisation de l'instance avec vérification du type
        if (SomeInterface.class.isAssignableFrom(clazz)) {
            ((SomeInterface) instance).doSomething();
        } else {
            System.out.println("Classe ne implémente pas l'interface requise.");
        }
    } catch (Exception e) {
        System.out.println("Erreur lors de l'instanciation de la classe : " + e.getMessage());
    }
} else {
    System.out.println("Nom de classe invalide.");
}
