```java
// अच्छा कोड: सुरक्षित उपयोग और सुविधा के साथ  
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public class UserAuth {
    public boolean authenticate(String username, String password) {
        // सुरक्षित उपयोग: पासवर्ड को हेश करके संग्रह करें  
        String hashedPassword = hashPassword(password);
        String storedHash = getStoredHash(username);
        return hashedPassword.equals(storedHash);
    }

    private String hashPassword(String password) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hashedBytes = md.digest(password.getBytes());
            return Base64.getEncoder().encodeToString(hashedBytes);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not found", e);
        }
    }

    private String getStoredHash(String username) {
        // सुरक्षित उपयोग: डेटाबेस से हेश के लिए अच्छा तरीका  
        // अच्छा: इस तरह के सुरक्षित उपयोग सुविधा को बढ़ाता है और सुरक्षा को बरकरार रखता है  
        // वास्तविक अनुप्रयोग में डेटाबेस कनेक्शन का उपयोग करें  
        try (BufferedReader reader = new BufferedReader(new FileReader("users.txt"))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] parts = line.split(":");
                if (parts[0].equals(username)) {
                    return parts[1];
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return null;
    }
}
```

