// Corretto: validazione degli input prima dell'uso dell'API Java
public class SecureExample {
    public static void main(String[] args) {
        String userInput = "http://example.com"; // Input utente non controllato

        // Validazione degli input: verifica che l'URL sia ben formato e inizi con http:// o https://
        if (isValidUrl(userInput)) {
            try {
                java.net.URL url = new java.net.URL(userInput);
                java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
                connection.setRequestMethod("GET");

                // Invia la richiesta e ricevi risposta (solo per dimostrazione)
                int responseCode = connection.getResponseCode();
                System.out.println("Risposta del server: " + responseCode);

            } catch (Exception e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("URL non valido o non sicuro.");
        }
    }

    // Funzione di validazione semplice per verificare lo schema dell'URL
    private static boolean isValidUrl(String url) {
        return url != null && url.matches("^(https?://)?[a-zA-Z0-9.-]+\\.[a-zA-Z]{2,}(?:/[a-zA-Z0-9.-]*)*$");
    }
}
