{
  "titulo": "Análisis de la correlación entre entornos de ritmo rápido y desarrollo de TDAH en estudiantes",
  "objetivo": "Investigar si existe una relación estadística significativa entre la exposición a ambientes con ritmo acelerado y el desarrollo de Trastorno por Déficit de Atención e Hiperactividad (TDAH) en estudiantes.",
  "metodologia": {
    "diseño": "Estudio observacional longitudinal",
    "muestra": {
      "tamano": 1200,
      "criterios_de_inclusion": [
        "Edad entre 6 y 18 años",
        "Residencia en zonas urbanas con alta densidad de actividades",
        "Diagnóstico clínico confirmado de TDAH o no diagnosticado"
      ],
      "criterios_de_exclusion": [
        "Historial de trastornos neurológicos",
        "Uso prolongado de medicamentos psicoactivos",
        "Familiares con diagnóstico de TDAH"
      ]
